css:
body.theme-default{--k-accent:#1f5eff;--k-accent-dark:#1c232c;--k-accent-2:#4d80ff;--k-soft:#dfe6f2;--k-ink:#1c232c;--k-muted:#5d6876;--k-line:#c3cbd6;--k-panel:#fff;--k-bg:#e7ebf0;--k-warn:#ff6a3d;--k-good:#1f5eff;--k-bad:#c2416b;--k-radius:6px;--k-shadow:none;
 --chart-1:#1f5eff;--chart-2:#1c232c;--chart-3:#ff6a3d;--chart-4:#7f9cf5;--chart-5:#c2416b;--chart-6:#9aa5b3;--chart-ink:#1c232c;--chart-muted:#5d6876;--chart-grid:#cfd6df;
 font-family:"Malgun Gothic","Apple SD Gothic Neo","Noto Sans KR",sans-serif}
.num,.cover-q,.gauge-big,.mv{font-family:"Bahnschrift","DIN Alternate","Avenir Next Condensed","Malgun Gothic",sans-serif;font-variant-numeric:tabular-nums;letter-spacing:0}
#stage.composed-scene{background:#e7ebf0;padding:32px 50px 26px;gap:11px}
.composed-scene .deck-top{color:#5d6876;font-size:14px}
.composed-scene .deck-mark i{background:#ff6a3d;border-radius:2px}
.composed-scene .eyebrow{color:#ff6a3d;font-weight:800;font-size:16px;margin:0}
.composed-scene .scene-title{font-size:41px;font-weight:800;letter-spacing:-.03em;color:#1c232c;max-width:none;line-height:1.15}
.composed-scene .scene-title em{color:#1f5eff}
.composed-scene .lead.summary{font-size:16.5px;background:#fff;border-left:5px solid #1c232c;padding:8px 16px;border-radius:0}
.composed-scene .scene-bottom{border-top:0;background:#1c232c;color:#fff;padding:9px 18px;border-radius:4px}
.composed-scene .message{font-size:18px;font-weight:600}
.composed-scene .message-label{background:#ff6a3d;color:#fff;padding:3px 10px;margin-right:14px;font-size:14px;border-radius:3px}
.composed-scene .source{color:#c3cbd6;font-size:12px}
.scene-body.composed{font-size:15px}
.k-panel{padding:14px 16px;gap:8px}
.k-band{margin:-14px -16px 2px;padding:8px 16px;font-size:15px;text-align:left;background:#1c232c}
.k-chip{font-style:normal}
.reveal-spotlight [data-step].focus{box-shadow:0 0 0 2px #1f5eff}
.reveal-spotlight [data-step].dim{opacity:.3;filter:grayscale(1)}
.k-matrix [data-step].focus,.fstrip.focus,.kpis.focus{box-shadow:none}
button[data-goto]{border-color:#1c232c;color:#1c232c;border-radius:4px;background:#fff}
button[data-goto]:hover{background:#1c232c;color:#fff}
.heat-ink{color:#ff6a3d}
.k-rows>*{font-size:14.5px}
.k-rows b{font-size:19px;font-weight:700}
.k-rows b.big{font-size:28px;color:#ff6a3d}
.k-badge{font-style:normal;flex:none;min-width:64px;border-radius:4px;background:#1c232c}
.k-stat{background:#fff;border:1px solid var(--k-line);padding:10px 16px}
.k-stat>b{font-size:32px;font-weight:600;color:#1c232c}

.cover{display:grid;grid-template-columns:320px minmax(0,1fr) minmax(0,1.1fr);gap:14px;flex:1;min-height:0}
.cover-art{background:linear-gradient(160deg,#1c232c,#2d394b);border-radius:6px;display:flex;flex-direction:column;align-items:center;padding:16px 16px 12px;min-height:0}
.cover-art svg{flex:1;min-height:0;width:100%}
.steam{fill:none;stroke:#ff6a3d;stroke-width:5;stroke-linecap:round}
.cover-q{font-size:84px;font-weight:700;fill:#fff}
.cover-q-sub{font-size:22px;fill:#dfe6f2}
.cover-tag{margin:6px 0 0;color:#dfe6f2;font-size:13px;letter-spacing:.03em}
.cover-nums{display:flex;flex-direction:column;gap:10px;min-height:0}
.cover-kicker{margin:0;font-weight:800;color:#5d6876;font-size:15px}
.bign{flex:1;background:#fff;border:1px solid var(--k-line);border-left:6px solid #1f5eff;border-radius:6px;padding:8px 20px;display:flex;flex-direction:column;justify-content:center;min-height:0}
.bign:nth-child(2){border-left-color:#ff6a3d}
.bign b{font-size:54px;font-weight:600;line-height:1.05;color:#1c232c}
.bign b small{font-size:22px;color:#5d6876;margin-left:4px}
.bign span{font-size:16px;color:#5d6876}
.bign em{font-style:normal;color:#ff6a3d;font-weight:800}
.toc{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;flex:1;min-height:0}
.toc li{flex:1;display:grid;grid-template-columns:46px 1fr;column-gap:10px;align-content:center;border-bottom:1px dashed var(--k-line)}
.toc li:last-child{border-bottom:0}
.toc b{grid-row:span 2;font-size:28px;color:#1f5eff;align-self:center}
.toc span{font-size:18px;font-weight:800}
.toc small{font-size:14px;color:#5d6876}

.sum{display:grid;grid-template-columns:260px minmax(0,1fr) minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);gap:12px;flex:1;min-height:0}
.gauge{grid-row:span 2;margin:0;padding:10px 8px;align-items:center}
.gauge svg{flex:1;min-height:0;width:100%}
.gauge figcaption{font-size:12px;color:#5d6876;text-align:center}
.gauge-label{font-size:24px;font-weight:700;fill:#1c232c}
.gauge-label.heat{fill:#ff6a3d}
.gauge-big{font-size:56px;font-weight:700;fill:#fff}
.kpis{grid-column:span 2;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.kt{background:#fff;border:1px solid var(--k-line);border-top:4px solid #1c232c;border-radius:6px;padding:10px 14px;display:flex;flex-direction:column;gap:3px;min-width:0}
.kt.hot{border-top-color:#ff6a3d}
.kt>span{font-size:14px;font-weight:800;color:#5d6876}
.kt>b{font-size:32px;font-weight:600;line-height:1.1;white-space:nowrap}
.kt>b small{font-size:15px;color:#5d6876;margin-left:3px}
.kt>em{font-style:normal;font-size:14px}
.kt strong{color:#ff6a3d}
.kt-sub{font-size:13px;color:#5d6876;border-top:1px dashed var(--k-line);padding-top:4px;margin-top:auto}
.kt .k-progress{margin-top:auto;height:7px}
.kt.hot .k-progress>i{background:#ff6a3d}
.rb-head{display:flex;justify-content:space-between;font-size:12px;color:#5d6876}
.rb-head u{display:inline-block;width:3px;height:12px;background:#ff6a3d;vertical-align:-2px;margin-right:4px}
.rb{display:grid;grid-template-columns:82px minmax(0,1fr) 58px 92px;align-items:center;gap:10px;flex:1}
.rb>span{font-weight:700;font-size:15px}
.rb-track{position:relative;height:20px;background:#eef1f5}
.rb-track i{display:block;height:100%;background:#1c232c}
.rb.best .rb-track i{background:#1f5eff}
.rb.low .rb-track i{background:#c2416b}
.rb-track u{position:absolute;top:-4px;bottom:-4px;width:3px;background:#ff6a3d}
.rb b{font-size:22px;text-align:right}
.rb.best b{color:#1f5eff}
.rb.low b{color:#c2416b}
.rb small{font-size:12px;color:#5d6876}
.why-2{margin:2px 0 0;font-size:14.5px;line-height:1.5;border-top:1px dashed var(--k-line);padding-top:8px}
.why-2 b{color:#ff6a3d;margin-right:6px}
.act i{flex:none;width:24px;height:24px;border-radius:50%;background:#1c232c;color:#fff;display:grid;place-items:center;font-style:normal;font-size:13px;font-weight:800}
.act b{color:#1f5eff;font-size:17px}
.ask button,.re button{align-self:flex-start}

.ctx{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,1.2fr);gap:12px;flex:1;min-height:0}
.cmp{display:flex;flex-direction:column;gap:6px}
.cmp-h{margin:2px 0 0;font-size:13px;font-weight:800;color:#5d6876}
.cmp-row{display:grid;grid-template-columns:36px minmax(0,1fr) 62px;gap:8px;align-items:center;font-size:14px}
.cmp-track{height:22px;background:#eef1f5}
.cmp-track i{display:block;height:100%;background:#1c232c;position:relative}
.cmp-track i.tgt{background:#9aa5b3}
.cmp-track u{position:absolute;right:0;top:0;height:100%;background:#ff6a3d}
.cmp-row b{font-size:20px;text-align:right}
.period{margin-top:auto}
.months{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:4px}
.months div{background:#eef1f5;padding:8px 10px;display:flex;flex-direction:column}
.months div.camp{background:#dfe6f2;border-bottom:4px solid #1f5eff}
.months span{font-size:13px;color:#5d6876}
.months b{font-size:22px}
.camp-note{margin:4px 0 0 34%;font-size:12px;color:#1f5eff;font-weight:800;text-align:center}
.mk{display:flex;flex-direction:column;gap:8px;flex:1;min-height:0}
.mk-card{display:flex;gap:12px;align-items:flex-start;background:#f4f6f9;border-radius:6px;padding:10px 12px;flex:1}
.mk-card>div{flex:1;min-width:0}
.mk-card svg{flex:none;width:44px;height:44px;fill:none;stroke:#1f5eff;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.mk-card.warn svg{stroke:#c2416b}
.mk-card b{display:block;font-size:17px}
.mk-card span{display:block;font-size:14px;color:#5d6876;line-height:1.45}
.mk-card .k-chips{margin:6px 0 0}
.mk-arrow{text-align:center;font-size:18px;color:#5d6876;line-height:1}
.verdict-card{background:#1c232c;color:#fff;flex:1.2}
.verdict-card b{color:#ff6a3d}
.diff{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0 0}
.diff span{background:#ffffff14;border:1px solid #ffffff33;padding:8px 10px;font-size:20px;font-weight:800;color:#fff;display:flex;flex-direction:column}
.diff small{font-size:12px;font-weight:600;color:#c3cbd6}
.persona{display:flex;gap:12px;align-items:center;background:#f4f6f9;padding:8px 12px;border-radius:6px}
.persona svg{flex:none;width:48px;height:48px;fill:#1f5eff}
.persona path{fill:#1c232c}
.persona b{display:block;font-size:21px}
.persona span{font-size:14px;color:#5d6876}
.motive{display:grid;grid-template-columns:1fr 1.4fr;gap:8px}
.motive span{display:flex;align-items:center;gap:10px;background:#f4f6f9;padding:6px 10px;font-size:14px;font-weight:700}
.motive b{font-size:18px;color:#1f5eff;white-space:nowrap}
.touch{display:grid;grid-template-columns:auto minmax(30px,1fr) auto;gap:6px 8px;align-items:center}
.touch .t{font-size:14px;font-weight:700;background:#eef1f5;padding:3px 10px;border-radius:999px;text-align:center}
.touch svg{width:100%;height:10px;overflow:visible}
.touch line{stroke:#1f5eff;stroke-width:2}
.touch .c{font-size:14px;font-weight:800;color:#fff;background:#1f5eff;padding:3px 10px;border-radius:4px}

.ch-wrap,.pl-wrap{display:flex;flex-direction:column;gap:8px;flex:1;min-height:0}
.k-matrix{gap:6px}
.k-mx-col{background:#1c232c;border-radius:4px;padding:7px 14px;font-size:17px}
.k-mx-col small{color:#9fb4ff}
.k-mx-col.best{background:#1f5eff}
.k-mx-col.best small{color:#fff}
.k-mx-col.low small{color:#ff9a7a}
.k-mx-col.total{background:#5d6876}
.k-mx-col.total small{color:#e7ebf0}
.k-mx-row{background:#dfe6f2;color:#1c232c;border-radius:4px;font-size:15px;display:flex;flex-direction:column;justify-content:center;align-items:center}
.k-mx-row small{display:block;font-size:11px;font-weight:600;color:#5d6876}
.k-mx-cell{border-radius:4px;padding:8px 12px}
.bar-cell,.roas-cell{flex-direction:column;align-items:stretch;justify-content:center;gap:5px}
.bar-cell>span{font-size:20px;font-weight:600;display:flex;align-items:baseline;justify-content:space-between}
.bar-cell em{font-style:normal;font-size:13px;color:#5d6876}
.bar-cell>small{font-size:12px;color:#5d6876}
.mb{height:12px;background:#eef1f5}
.mb i{display:block;height:100%;background:#1f5eff}
.mb i.spend{background:#9aa5b3}
.roas-cell b{font-size:26px;font-weight:600}
.roas-cell.best b{color:#1f5eff}
.roas-cell.low b{color:#c2416b}
.rt{position:relative;height:10px;background:#eef1f5}
.rt i{display:block;height:100%;background:#1c232c}
.roas-cell.best .rt i{background:#1f5eff}
.roas-cell.low .rt i{background:#c2416b}
.rt u{position:absolute;left:58.33%;top:-4px;bottom:-4px;width:3px;background:#ff6a3d}
.judge{font-weight:700;font-size:14.5px;line-height:1.4}
.judge.best{background:#e8eeff;color:#1338b0}
.judge.low{background:#fbe9ee;color:#a3284f}
.ch-foot{display:flex;justify-content:space-between;align-items:center;font-size:13px;color:#5d6876}
.lg{display:inline-block;width:12px;height:12px;margin:0 5px 0 12px;vertical-align:-1px}
.lg.spend{background:#9aa5b3;margin-left:0}
.lg.rev{background:#1f5eff}
.lg.tg{width:3px;background:#ff6a3d}

.fn{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr) minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);gap:12px;flex:1;min-height:0}
.fstrip{grid-column:1/-1;display:grid;grid-template-columns:1fr 104px 1fr 104px 1fr 104px 1fr 104px 1fr;background:#fff;border:1px solid var(--k-line);border-radius:6px;padding:12px 16px}
.fs{display:flex;flex-direction:column;justify-content:center;border-left:4px solid #1c232c;padding:2px 12px}
.fs span{font-size:14px;font-weight:800;color:#5d6876}
.fs b{font-size:32px;font-weight:600;white-space:nowrap}
.fs b small{font-size:15px;color:#5d6876;margin-left:3px}
.fs.hot{border-left-color:#ff6a3d}
.fs.hot b{color:#ff6a3d}
.fr{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px}
.fr b{font-size:20px;color:#1f5eff}
.fr svg{width:70px;height:12px;overflow:visible}
.fr line{stroke:#1f5eff;stroke-width:2}
.fr path{fill:#1f5eff}
.fr small{font-size:11px;color:#5d6876}
.re-big{display:flex;align-items:baseline;gap:12px}
.re-big b{font-size:52px;font-weight:600;color:#1f5eff;line-height:1.05}
.re-big b small{font-size:20px;color:#5d6876}
.re-big span{font-size:15px;color:#5d6876}

.mo-wrap{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:12px;flex:1;min-height:0}
.mo-chart svg{flex:1;min-height:0;width:100%}
.gl{stroke:#dfe3e9;stroke-width:1}
.gt{font-size:12px;fill:#5d6876}
.season{fill:#dfe6f2;opacity:.7}
.season-t{font-size:14px;font-weight:800;fill:#1f5eff}
.mo rect{fill:#1c232c}
.mo:last-of-type rect{fill:#1f5eff}
.mv{font-size:22px;font-weight:700;fill:#1c232c}
.ml{font-size:16px;font-weight:700;fill:#1c232c}
.md{font-size:15px;font-weight:800;fill:#ff6a3d}
.mo-side{display:flex;flex-direction:column;gap:12px;min-height:0}
.mo-side>.k-panel:nth-child(2){flex:1}
.cum-bar{position:relative;display:flex;height:44px;background:#eef1f5;margin:22px 0 2px}
.cum-bar i{display:flex;align-items:center;height:100%;padding:0 8px;color:#fff;font-style:normal;font-size:12.5px;font-weight:700;white-space:nowrap;overflow:hidden;border-right:2px solid #fff}
.cum-bar .c7{background:#5d6876}
.cum-bar .c8{background:#1c232c}
.cum-bar .c9{background:#1f5eff}
.cum-bar u{position:absolute;top:-20px;bottom:-6px;width:0;border-left:3px dashed #ff6a3d;text-decoration:none}
.cum-bar u b{position:absolute;top:-3px;right:6px;font-size:12px;color:#ff6a3d;white-space:nowrap}
.cum-note{margin:6px 0 0;font-size:14px}
.cum-note b{color:#ff6a3d}

.mx-plan{font-size:15.5px}
.mx-plan .k-mx-cell.hl{background:#e8eeff;color:#1338b0}
.ask-bar{display:flex;align-items:center;gap:16px;background:#ff6a3d;color:#fff;border-radius:6px;padding:11px 18px}
.ask-k{background:#1c232c;padding:4px 12px;border-radius:3px;font-weight:800;font-size:14px}
.ask-t{flex:1;font-size:21px;font-weight:800}
.ask-t b{font-size:24px}
.bign{display:grid;grid-template-columns:minmax(0,1fr) 220px;align-items:center;gap:18px}
.bign>div:first-child{display:flex;flex-direction:column}
.mini{display:flex;flex-direction:column;gap:7px}
.mini p{margin:0;display:grid;grid-template-columns:30px minmax(0,1fr) 44px;align-items:center;gap:6px;font-size:12px;color:#5d6876}
.mini i{display:block;height:12px;background:#9aa5b3}
.mini p.on i{background:#1f5eff}
.mini b{font-size:14px;text-align:right;color:#1c232c}
.mini.steps{gap:0}
.mini.steps p{grid-template-columns:minmax(0,1fr) auto;border-bottom:1px dashed var(--k-line);padding:3px 0}
.mini.steps p:last-child{border-bottom:0}
.mini.steps p.on span,.mini.steps p.on b{color:#ff6a3d;font-weight:800}
.ctx{grid-template-rows:minmax(0,1fr) auto}
.ctx-strip{grid-column:1/-1}
.why-same{margin:8px 0 0;font-size:13px;color:#c3cbd6}
.diff span{font-size:22px;padding:12px}
.fs em{font-style:normal;font-size:12px;color:#5d6876}
.pc{flex-direction:column;align-items:flex-start;justify-content:center;gap:5px}
.pc b{font-size:30px;font-weight:600;color:#1c232c;line-height:1}
.pc.hl b{color:#1f5eff}
.pc span{font-size:15px;line-height:1.45}
.bk{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);gap:12px;flex:1;min-height:0}
.bk-table{grid-column:1/-1}
.bk-check .k-table{font-size:16px}
.bk-check .k-table td{padding:10px 12px}
.bign b{font-size:50px;white-space:nowrap}
.bign{grid-template-columns:minmax(0,1fr) 200px}
.mini p{grid-template-columns:32px minmax(0,1fr) 46px;white-space:nowrap}
.gauge-big{font-size:46px}
.rate2{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:6px}
.rate2 p{margin:0;background:#fff4ef;border:1px solid #ffd2c2;padding:8px 12px;display:flex;flex-direction:column}
.rate2 span{font-size:12px;font-weight:700;color:#5d6876}
.rate2 b{font-size:30px;font-weight:600;color:#ff6a3d;line-height:1.1}
.touch{flex:1;grid-auto-rows:minmax(34px,1fr)}
.touch .t,.touch .c{padding:7px 10px}
.bk-check .k-table td{padding:13px 12px}
.defs b{margin-left:0;min-width:82px;font-size:16px}
.mini b{font-size:14px;color:#1c232c;white-space:nowrap}
.mini.steps p.on b{color:#ff6a3d}
.bk-check .k-stats{margin-top:auto}
